import React, { useState, useEffect } from 'react';
import {
  MagnifyingGlassIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
  CheckIcon,
  XMarkIcon,
} from "@heroicons/react/24/outline";
import AdminSidebar from "../AdminSidebar";
import api from '../../../services/api';

export default function WalletLog() {
  const [walletRequests, setWalletRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    approved: 0,
    rejected: 0
  });

  useEffect(() => {
    fetchWalletRequests();
  }, []);

  const fetchWalletRequests = async () => {
    try {
      setLoading(true);
      const response = await api.get('/admin/wallet-requests');
      setWalletRequests(response.data || []);

      const pending = response.data?.filter(r => r.status === 'pending').length || 0;
      const approved = response.data?.filter(r => r.status === 'approved').length || 0;
      const rejected = response.data?.filter(r => r.status === 'rejected').length || 0;

      setStats({
        total: response.data?.length || 0,
        pending,
        approved,
        rejected
      });
    } catch (error) {
      console.error('Error fetching wallet requests:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (requestId) => {
    try {
      await api.post(`/admin/wallet-request/${requestId}/approve`);
      fetchWalletRequests();
      alert('Request approved successfully');
    } catch (error) {
      console.error('Error approving request:', error);
      alert('Failed to approve request');
    }
  };

  const handleReject = async (requestId) => {
    try {
      await api.post(`/admin/wallet-request/${requestId}/reject`);
      fetchWalletRequests();
      alert('Request rejected successfully');
    } catch (error) {
      console.error('Error rejecting request:', error);
      alert('Failed to reject request');
    }
  };

  const filteredRequests = walletRequests.filter(request =>
    request.user_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    request.user_email?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="flex h-screen bg-gradient-to-br from-gray-50 to-white">
      {/* Sidebar */}
      <AdminSidebar />

      {/* Main Content */}
      <div className="flex-1 overflow-hidden">
        {/* Header */}
        <div className="bg-white border-b shadow-sm">
          <div className="flex items-center justify-between px-8 py-6">
            <h2 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600">
              Wallet Requests
            </h2>
            <div className="w-10 h-10 bg-gradient-to-r from-blue-500 to-indigo-500 rounded-full flex items-center justify-center text-white font-semibold">
              AS
            </div>
          </div>
        </div>

        <div className="p-8 overflow-y-auto h-[calc(100vh-5rem)]">
          {/* Stats */}
          <div className="grid grid-cols-4 gap-4 mb-6">
            <div className="bg-white p-4 rounded-xl border border-gray-100">
              <p className="text-2xl font-bold text-gray-900">{stats.total}</p>
              <p className="text-gray-500 text-sm mt-1">Total Requests</p>
            </div>
            <div className="bg-white p-4 rounded-xl border border-gray-100">
              <p className="text-2xl font-bold text-yellow-600">{stats.pending}</p>
              <p className="text-gray-500 text-sm mt-1">Pending</p>
            </div>
            <div className="bg-white p-4 rounded-xl border border-gray-100">
              <p className="text-2xl font-bold text-green-600">{stats.approved}</p>
              <p className="text-gray-500 text-sm mt-1">Approved</p>
            </div>
            <div className="bg-white p-4 rounded-xl border border-gray-100">
              <p className="text-2xl font-bold text-red-600">{stats.rejected}</p>
              <p className="text-gray-500 text-sm mt-1">Rejected</p>
            </div>
          </div>

          {/* Search */}
          <div className="mb-6">
            <div className="relative">
              <MagnifyingGlassIcon className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search by user name or email..."
                className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500/20 focus:outline-none"
              />
            </div>
          </div>

          {/* Requests Table */}
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
            {loading ? (
              <div className="p-8 text-center">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto"></div>
                <p className="text-gray-500 mt-2">Loading wallet requests...</p>
              </div>
            ) : filteredRequests.length === 0 ? (
              <div className="p-8 text-center text-gray-500">
                No wallet requests found
              </div>
            ) : (
              <>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="text-left border-b text-gray-500 bg-gray-50">
                        <th className="px-6 py-3">User</th>
                        <th className="px-6 py-3">Email</th>
                        <th className="px-6 py-3">Amount</th>
                        <th className="px-6 py-3">Reason</th>
                        <th className="px-6 py-3">Requested</th>
                        <th className="px-6 py-3">Status</th>
                        <th className="px-6 py-3">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {filteredRequests.map((request) => (
                        <tr key={request.id} className="hover:bg-gray-50">
                          <td className="px-6 py-3 font-medium">{request.user_name}</td>
                          <td className="px-6 py-3 text-gray-600">{request.user_email}</td>
                          <td className="px-6 py-3 font-semibold text-blue-600">SC {request.amount}</td>
                          <td className="px-6 py-3">{request.reason}</td>
                          <td className="px-6 py-3">
                            {new Date(request.created_at).toLocaleDateString()}
                          </td>
                          <td className="px-6 py-3">
                            <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                              request.status === 'pending' ? 'bg-yellow-100 text-yellow-700' :
                              request.status === 'approved' ? 'bg-green-100 text-green-700' :
                              'bg-red-100 text-red-700'
                            }`}>
                              {request.status?.charAt(0).toUpperCase() + request.status?.slice(1)}
                            </span>
                          </td>
                          <td className="px-6 py-3">
                            {request.status === 'pending' ? (
                              <div className="flex gap-2">
                                <button
                                  onClick={() => handleApprove(request.id)}
                                  className="p-2 text-green-600 hover:bg-green-50 rounded-lg transition-colors"
                                  title="Approve"
                                >
                                  <CheckIcon className="w-5 h-5" />
                                </button>
                                <button
                                  onClick={() => handleReject(request.id)}
                                  className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                  title="Reject"
                                >
                                  <XMarkIcon className="w-5 h-5" />
                                </button>
                              </div>
                            ) : (
                              <span className="text-gray-400 text-sm">Completed</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>

                {/* Pagination */}
                <div className="flex justify-between items-center p-6 border-t bg-gray-50">
                  <p className="text-sm text-gray-500">
                    Showing 1 to {filteredRequests.length} of {walletRequests.length} results
                  </p>
                  <div className="flex space-x-2">
                    <button className="p-2 border rounded-lg hover:bg-gray-200">
                      <ChevronLeftIcon className="h-5 w-5" />
                    </button>
                    <button className="px-3 py-1 border rounded-lg bg-blue-600 text-white">1</button>
                    <button className="px-3 py-1 border rounded-lg hover:bg-gray-200">2</button>
                    <button className="p-2 border rounded-lg hover:bg-gray-200">
                      <ChevronRightIcon className="h-5 w-5" />
                    </button>
                  </div>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
